\label{exm1.3}
{\rm For a general parabolic $P$, $X_P^S$ does not necessarily have components of the same dimension. For example, take $G=\operatorname{\mathrm{GL}}_n(\mathbbm{C})$ and $P$ a maximal parabolic subgroup such that $X_P=\mathbbm{P}^{n-1}$. Take $S\subset T$ be the subgroup of order $2$ generated by the diagonal element $\left((+1)^m,(-1)^{n-m}\right)$, which is $+1$ along the first $m$ entries of the diagonal and $-1$ in the following  $(n-m)$ entries. 
 In this case,}
$$
X^S_P=\mathbbm{P}^{m-1}\sqcup \mathbbm{P}^{n-m-1}.
$$
{\rm This provides a counter example if $n\neq 2m$.}

\label{rmk1.4}
    {\rm (1) Following the notation and assumptions of Proposition \ref{pps1.1},} 
$$
Y_S=\left\{ v\in W^P:~ \mathcal{U}_v^S=e \right\},
$$
{\rm where $\mathcal{U}_v\subset G$ is the unipotent group with Lie algebra} 
$$
\bigoplus_{\alpha\in R^+ \cap v R_P^-}  \mathfrak{g}_\alpha = \bigoplus_{\alpha\in R^+ \cap v R^-} \mathfrak{g}_\alpha, 
$$
{\rm where $R^+$ is the set of positive roots of $G$ and $R^-_P$ is the set of  roots of the opposite unipotent radical of $P$. 
This follows since}
$$
B^S v~P/P= \mathcal{U}_v^S\cdot vP/P.
$$
\vskip1ex

    {\rm (2) If $S$ is generated by a finite order $t\in T$ which is regular, i.e., $e^\alpha(t)\neq 1$ for any root $\alpha$ of $G$, then $B^S=T$ (and hence $(G^S)^o=T$), $Y_S=W^P$ and the connected components of $X_P^S$ are all points (use Proposition \ref{pps1.1}).}

\label{lem1.5}
Following Proposition \ref{pps1.1}, we get the following:
\begin{equation}\label{eq6}
\sum_{v\in Y_S} \# \left( W((G^S)^o)/W\left((G^S)^o\cap (vPv^{-1})\right)\right)=\# W^P,
\end{equation}
 where $W(H)$ is the Weyl group of $H$. 

In particular,
\begin{equation}\label{eq7}
\# Y_S\geq \frac{\# W^P}{\#W((G^S)^o)}.
\end{equation}
For $P=B$, in fact we have the equality 
\begin{equation}\label{eq8}
\#Y_S =\frac{\# W}{\#W((G^S)^o)}.
\end{equation}

Use \cite[Theorem 4.6]{AS} together with the identities (\ref{eq6}) and (\ref{eq12}) for the line bundle $\mathcal{L}(n\lambda)$ over $X_P$. 
By the Borel-Weil-Bott Theorem, 
\begin{eqnarray*}
&&H^i\left(X_P,\mathcal{L}(n\lambda)\right)=0,\quad \mbox{for all } i>0\\
\mbox{and} && H^0\left(X_P,\mathcal{L}(n\lambda)\right)= V(n\lambda)^*. 
\end{eqnarray*}
Thus, 
\begin{eqnarray*}
\sum_{i\geq0}(-1)^i \mbox{Trace}\left(t,~H^i\left(X_P,\mathcal{L}(n\lambda)\right)\right)&=& \mbox{ch}\left(t, V(n\lambda)^*\right)\\
&=& \mbox{ch}\left(t^{-1}, V(n\lambda)\right).
\end{eqnarray*}

\label{cry2.2}
For any fixed $0\leq p<r$, $\chi_{\lambda_{|\left\{n\equiv p(mod\,r)\right\}}}^t$ is a polynomial function in $n$ of degree
$\leq \max_{v\in Y_S}\left\{d_v\right\}$.

Moreover, the coefficient of $n^{d_v}$ in $D_v^t(n,\lambda)$ restricted to $\{ n\equiv p (mod\, r) \}$ is equal to 
\begin{equation}\label{eq14}
\frac{1}{d_v!}\int_{X_P^t(v)} c_1 \left(\mathcal{L}(\lambda)_{|_{X_P^t(v)}}\right)^{d_v} \frac{e^{-pv\lambda}(t)}{\prod_{\alpha\in \left(v R^+_P\right)\backslash R\left(\left(G^t\right)^o\right)}\left(1-e^{\alpha}(t)\right)}.
\end{equation}

\label{rmk2.3}
{\rm Since $\mathcal{L}(\lambda)$ is an ample line bundle over $X_P=G/P$, by Wirtinger theorem (cf. \cite[Chapter 0, $\S$2]{GH}), for any $v\in Y_S$,} 
$$
\int_{X_P^t(v)}c_1\left(\mathcal{L}(\lambda)|_{X_P^t(v)}\right)^{d_v}>0.
$$

\label{exm2.6}
{\rm Let the assumption be as in Theorem \ref{thm2.1}. Assume further that $t\in T$ is a regular element (i.e., $e^\alpha(t)\neq 1$ for any root $\alpha$ of $G$) of finite order $r$. Then, the function 
$n\mapsto \mbox{ch}\left(t^{-1}, V(n\lambda)\right)$ is the constant function 1, when $n$ is restricted to $r\mathbbm{Z}_{\geq0}$. }
